<div class="topline"><span><?= e(t('OPTIONAL WORKSPACE')) ?></span><span><?= e(t('Local records for a small business.')) ?></span></div><header class="page-header"><div><h1><?= e(t('Small business')) ?></h1><p class="muted"><?= e(t('Track clients, project hours, income and costs. These are separate from personal Money accounts.')) ?></p></div></header><?php require ROOT.'/app/Core/views/notices.php'; ?>
<section class="card"><h2><?= e(t('New project')) ?></h2><form class="form-grid" method="post" action="/small-business/project"><?= csrf_field() ?><label><?= e(t('Project name')) ?><input name="name" maxlength="200" required></label><label><?= e(t('Client')) ?><input name="client" maxlength="200"></label><label><?= e(t('Hourly rate (Rs., optional)')) ?><input type="number" name="hourly_rate" min="0" step="0.01" value="0"></label><label><?= e(t('Notes')) ?><input name="notes" maxlength="2000"></label><div class="full"><button><?= e(t('Create project')) ?></button></div></form></section>
<section class="card"><h2><?= e(t('Projects')) ?></h2><?php foreach ($projects as $row): ?><div class="simple-row"><span><a href="/small-business/project/<?= e($row['id']) ?>"><strong><?= e($row['name']) ?></strong></a><small><?= e($row['client']) ?> · <?= e($row['status']) ?> · <?= e(number_format($row['hours'],2)) ?> <?= e(t('hours')) ?></small></span><span><?= e(t('Income')) ?> <?= money($row['income']) ?> <?= e(t('· Cost')) ?> <?= money($row['cost']) ?> <?= e(t('· Profit')) ?> <?= money($row['income']-$row['cost']) ?></span></div><?php endforeach; ?><?php if (!$projects): ?><p class="muted"><?= e(t('No projects yet.')) ?></p><?php endif; ?></section>
